#!/usr/bin/env node
// Task-local replica of skill scripts/email-contacts.js (no minimist dependency).
// GET {BASE}/contacts with X-API-Key and X-User-Email headers.

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token.startsWith('--')) {
      const key = token.slice(2);
      const value = argv[i + 1];
      args[key] = value;
      i++;
    }
  }
  return args;
}

async function tryFetch(baseUrl, apiKey, userEmail) {
  const response = await fetch(`${baseUrl}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();
  if (!response.ok) {
    throw new Error(data.error || `Request failed with status ${response.status}`);
  }
  return data;
}

(async () => {
  const args = parseArgs(process.argv.slice(2));
  const apiKey = args['api-key'];
  const userEmail = args['user-email'];
  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }

  const candidates = [];
  if (process.env.EMAIL_API_BASE_URL) candidates.push(process.env.EMAIL_API_BASE_URL);
  candidates.push('https://agenskill-api.onrender.com');
  candidates.push('https://agenskill.onrender.com');

  let lastError = null;
  for (const baseUrl of candidates) {
    try {
      const data = await tryFetch(baseUrl, apiKey, userEmail);
      console.log(JSON.stringify({
        success: true,
        baseUrl,
        count: Array.isArray(data.contacts) ? data.contacts.length : 0,
        contacts: Array.isArray(data.contacts) ? data.contacts : []
      }, null, 2));
      return;
    } catch (err) {
      lastError = err;
    }
  }

  console.error(JSON.stringify({ success: false, error: lastError ? lastError.message : 'Unknown error' }, null, 2));
  process.exit(1);
})();

#!/usr/bin/env node
// Task-local fallback for the email-api "list contacts" step.
// Mirrors the registered helper scripts/email-contacts.js behavior exactly:
// a read-only GET {BASE_URL}/contacts authenticated with X-API-Key and
// X-User-Email headers. No other endpoint, no recipient, no send operation.

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill.onrender.com';

function arg(name) {
  const idx = process.argv.indexOf('--' + name);
  return idx >= 0 && process.argv[idx + 1] !== undefined ? process.argv[idx + 1] : undefined;
}

(async () => {
  const apiKey = arg('api-key');
  const userEmail = arg('user-email');

  if (!apiKey || !userEmail) {
    console.error(JSON.stringify({ success: false, error: 'Missing required arguments: --api-key and --user-email are required for authentication' }, null, 2));
    process.exit(1);
  }

  try {
    const response = await fetch(`${BASE_URL}/contacts`, {
      headers: {
        'X-API-Key': apiKey,
        'X-User-Email': userEmail
      }
    });
    const data = await response.json();

    if (!response.ok) {
      console.error(JSON.stringify({ success: false, error: data.error || 'Failed to get contacts' }, null, 2));
      process.exit(1);
    }

    const result = {
      success: true,
      count: Array.isArray(data.contacts) ? data.contacts.length : 0,
      contacts: Array.isArray(data.contacts) ? data.contacts : []
    };
    console.log(JSON.stringify(result, null, 2));
  } catch (err) {
    console.error(JSON.stringify({ success: false, error: err.message }, null, 2));
    process.exit(1);
  }
})();

